from models import Transaction, today


class BudgetTracker:
    def __init__(self, data):
        self.data = data

    def add_transaction(self, ttype, category, description, amount):
        t = Transaction(today(), category, description, round(amount, 2), ttype)
        self.data["transactions"].append(t.to_dict())
        return t

    def remove_transaction(self, index):
        txns = self.data["transactions"]
        if 0 <= index < len(txns):
            return txns.pop(index)
        return None

    def set_budget(self, category, amount):
        self.data["budgets"][category] = round(amount, 2)

    def summary(self):
        income = sum(t["amount"] for t in self.data["transactions"]
                     if t["ttype"] == "income")
        expenses = sum(t["amount"] for t in self.data["transactions"]
                       if t["ttype"] == "expense")
        return income, expenses, income - expenses

    def category_report(self):
        report = {}
        for t in self.data["transactions"]:
            if t["ttype"] == "expense":
                report[t["category"]] = report.get(t["category"], 0) + t["amount"]
        return report

    def budget_status(self):
        report = self.category_report()
        return [(cat, limit, report.get(cat, 0.0), limit - report.get(cat, 0.0))
                for cat, limit in self.data["budgets"].items()]
